INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(10,'软考',3,'case','某 Web 服务器上线一段时间后监控告警：机器上有几万条处于 TIME_WAIT 状态的 TCP 连接，随后新建连接开始报 "Cannot assign requested address"。\n\n请回答：\n（1）写出 TCP 四次挥手四个报文的标志位与序号字段，并给出双方的状态变迁（设主动关闭方为 A，被动关闭方为 B，A 的最后一个字节序号为 u，B 的为 v）；\n（2）TIME_WAIT 出现在哪一方？持续多久？它的两个作用是什么？\n（3）大量 TIME_WAIT 会带来什么危害？\n（4）给出合理解决方案，并说明为什么"把 SO_LINGER 设为 0 强制关闭"不是好办法。',
'[]','',
'解题路径是先复原四次挥手与状态机，再定位 TIME_WAIT 的归属：只有**主动关闭方**才会进入 TIME_WAIT，因此服务器出现大量 TIME_WAIT 说明是服务器自己在主动关闭连接（短连接场景）。关键点在于理解 TIME_WAIT 的两大作用——保证最后一个 ACK 能重发、让旧连接的残留报文在网络中消散，因此不能简单地"消灭"它，而应减少主动关闭的次数。',
'## （1）四次挥手与状态变迁\n1. **A → B**：`FIN = 1, seq = u`；A：ESTABLISHED → **FIN_WAIT_1**\n2. **B → A**：`ACK = 1, ack = u + 1`；B：ESTABLISHED → **CLOSE_WAIT**；A 收到后 → **FIN_WAIT_2**（半关闭，A 仍可收 B 的数据）\n3. **B → A**：`FIN = 1, seq = v`（B 把剩余数据发完后）\n；B：CLOSE_WAIT → **LAST_ACK**\n4. **A → B**：`ACK = 1, ack = v + 1`；A：FIN_WAIT_2 → **TIME_WAIT**，等待 **2MSL** 后进入 CLOSED；B 收到该 ACK 后立即 → **CLOSED**\n\n之所以是"四次"而不是"三次"，是因为 B 收到 FIN 后可能还有数据没发完，ACK 与 FIN 通常分开发（开启延迟确认时也可能捎带合并为三次）。\n\n## （2）TIME_WAIT 的归属与时长\nTIME_WAIT 只出现在**主动发起关闭的一方**（本例即服务器），持续 **2MSL**（Maximum Segment Lifetime 的 2 倍；Linux 上 MSL 取 30 s，故约 **60 s**）。\n两个作用：\n① **可靠地终止连接**：第 4 个 ACK 可能丢失，B 超时后会重发 FIN；若 A 已直接关闭，就无法再回 ACK，B 将永远停在 LAST_ACK。保留 TIME_WAIT 使 A 能重发 ACK。\n② **让旧连接的残留报文在网络中消散**：避免迟到的报文被"复用同一四元组（源IP:源端口:目的IP:目的端口）的新连接"误收，造成数据错乱。\n\n## （3）危害\n- 每个 TIME_WAIT 条目占用一个四元组，主动关闭方**临时端口被耗尽**，新连接无法建立（本例的报错正是端口分配失败）；\n- 占用内核内存与哈希表项，连接数极大时查找变慢；\n- 若服务器同时是客户端（如反向代理访问后端），会先耗尽自己的出向端口。\n\n## （4）解决方案\n- **减少主动关闭**：让客户端先关闭（调整应用关闭顺序）；开启 HTTP **Keep-Alive**、使用长连接/连接池，把短连接变成长连接；\n- **扩大可用端口范围**：调大 `net.ipv4.ip_local_port_range`（如 1024~65535）、`net.ipv4.tcp_max_tw_buckets`；\n- 对**出向**连接可开启 `net.ipv4.tcp_tw_reuse = 1`（依赖 TCP 时间戳，且仅对新发起的连接有效）；\n- 负载均衡或反向代理场景下用长连接回源。\n**不推荐**：`tcp_tw_recycle` 在 NAT 环境下会因时间戳错乱丢弃合法连接（Linux 4.12 已移除）；把 `SO_LINGER` 设为 0 会直接发 **RST** 强制关闭，虽然绕过了 TIME_WAIT，但会**丢弃发送缓冲区中尚未发完的数据**、让对端收到异常连接重置，属于掩盖问题而非解决问题，且可能把旧报文污染新连接。',
'[{"point":"正确写出四次挥手四个报文的标志位与序号，并给出 FIN_WAIT_1/FIN_WAIT_2/CLOSE_WAIT/LAST_ACK/TIME_WAIT 的状态变迁","score":4},{"point":"说明 TIME_WAIT 出现在主动关闭方，持续 2MSL（Linux 约 60 秒）","score":3},{"point":"说明 TIME_WAIT 的两个作用（重发最后的 ACK 保证可靠关闭、避免旧报文混入复用四元组的新连接）与端口耗尽的危害","score":3},{"point":"给出合理解决方案（Keep-Alive 长连接/连接池、让客户端主动关闭、扩大端口范围、tw_reuse），并指出 SO_LINGER=0 发 RST 会丢数据、属于掩盖问题","score":2}]',12),

(11,'期末',3,'case','主机 A（10.0.1.10/24）向主机 B（10.0.3.20/24）发送一个 IP 数据报，路径为 A → R1 → R2 → B，其中 R1 的入接口为 10.0.1.1、出接口为 10.0.2.1，R2 的入接口为 10.0.2.2、出接口为 10.0.3.1。\n\n请回答：\n（1）路由器收到一个 IP 数据报后的完整处理流程是什么？\n（2）数据报经过路由器时，IP 首部中哪些字段**会被修改**？哪些**保持不变**？\n（3）若数据报到达 R1 时 TTL = 1，会发生什么？\n（4）若出接口 MTU 小于数据报长度，分片在哪一端进行？目的主机如何把分片重组成原始数据报？',
'[]','',
'解题路径是"逐跳转发"模型：路由器工作在网络层，每跳都要做首部校验、TTL 递减、重算校验和、查路由表、再交给数据链路层重新封装成帧。关键点在于 IP 首部的源/目的地址**始终不变**（端到端语义），变的是 TTL、校验和以及链路层帧头；分片只在必要时的出接口做，重组只由目的主机做。',
'## （1）路由器处理流程\n1. 链路层收到帧，剥去帧头帧尾交给 IP 层；\n2. 检查版本、首部长度，并按**反码求和**计算首部校验和，校验出错直接丢弃（不产生差错报告）；\n3. 若是发给本机的（目的 IP 命中自己的接口）则上交上层，否则转发：**TTL 减 1**；若 TTL 变为 0 则丢弃并向源主机发送 **ICMP 超时报文（Type 11, Code 0）**（traceroute 正是利用这一点）；\n4. TTL 改变后**必须重新计算首部校验和**；\n5. 用目的 IP 查路由表，按**最长前缀匹配**找出下一跳 IP；\n6. 通过 ARP 查下一跳的 MAC 地址，交给链路层**重新封装成帧**（源 MAC 改为出接口 MAC，目的 MAC 改为下一跳 MAC）；\n7. 若出接口 MTU 小于数据报长度：DF = 0 则分片后发送；DF = 1 则丢弃并发 **ICMP 需要分片（Type 3, Code 4）**。\n\n## （2）首部字段的变化\n**被修改**：TTL（每跳减 1）、首部校验和；发生分片时还包括总长度、标志位 MF、片偏移。\n**保持不变**：版本、源 IP 地址、目的 IP 地址、协议字段、标识（Identification，各分片复制同一值）、服务类型、数据部分。\n链路层帧头每跳都会重写（MAC 地址逐跳变化），这是"网络层端到端、链路层点到点"的直接体现。\n\n## （3）TTL = 1 到达 R1\nR1 先把 TTL 减 1 得到 0，于是**丢弃**该数据报，并向源主机 A 发回 ICMP 超时报文；数据报不会继续转发到 R2。这保证了即使存在路由环路，报文也不会在网络中无限循环。\n\n## （4）分片与重组\n分片在**出接口 MTU 不足的那一端路由器**上进行（IPv4 允许路由器分片；IPv6 只允许源主机分片，路由器发 ICMPv6 Packet Too Big）。\n重组只在**目的主机 B** 完成，中间路由器不重组（否则分片后经过不同路径会无法还原）。\n重组依据：B 用**标识字段（Identification）+ 源 IP + 协议**判断哪些分片属于同一个数据报，按**片偏移 × 8** 排序，遇到 MF = 0 的分片即可确定总长度；若在重组定时器（通常 30 s 左右）超时前仍有分片未到齐，则丢弃全部分片并回送 ICMP 重组超时。',
'[{"point":"正确列出路由器处理流程（首部校验→TTL 减 1→重算校验和→查路由表最长前缀匹配→ARP 与重新封装）","score":3},{"point":"正确说明被修改的字段（TTL、首部校验和，分片时含总长度/标志/片偏移）与保持不变的字段（源目 IP、协议、标识）","score":3},{"point":"正确说明 TTL 减为 0 时丢弃并向源发 ICMP 超时报文","score":2},{"point":"说明分片在 MTU 不足的出接口进行、重组只在目的主机按标识与片偏移完成","score":2}]',10),

(46,'考研408',4,'case','三个路由器 A、B、C 依次相连（A—B—C），网络 N 直接连在 C 上。三个路由器运行 **RIP**（按"到直连网络距离为 1，到非直连网络距离 = 经过的路由器数 + 1"计，最大有效距离 15，16 表示不可达）。\n\n请回答：\n（1）稳定状态下，A、B、C 各自到网络 N 的距离是多少？\n（2）若 B 与 C 之间的链路突然断开，描述此后路由表的变化过程（这就是"计数到无穷"问题）；\n（3）给出至少三种解决慢收敛的措施并说明其原理；\n（4）与 RIP 相比，OSPF 为什么不会出现这种问题？',
'[]','',
'解题路径是理解距离向量算法的本质——每个路由器只"听信邻居告诉它的距离"，并不掌握全网拓扑，因此当真实路由失效后，一条从邻居学来的、本已过时的路由会被当作新路径反复传递，距离逐轮加一，直到抵达 16（不可达）才停止。关键点在于区分"好消息传得快"（一跳一跳迅速收敛）与"坏消息传得慢"（计数到无穷）。',
'## （1）稳定状态\n- C 到 N：**1**（直连）\n- B 到 N：**2**（经 C）\n- A 到 N：**3**（经 B、C）\n\n## （2）B—C 链路断开后的计数到无穷\n1. 断开后 B 到 N 的直连路径失效，C 也无法再通告 N 给 B；\n2. 但 A 仍会按 **30 秒** 一次的周期向 B 通告"我到 N 距离 3"；\n3. B 并不知道 A 的这条路由其实是**经由自己**的，于是把距离更新为 3 + 1 = **4**，下一跳改为 A；\n4. 下一轮 B 把"到 N 距离 4"通告给 A，A 更新为 **5**；A 再通告给 B，B 更新为 **6**……如此反复；\n5. 直到距离达到 **16（不可达）** 才判定 N 不可达。约需 13 轮更新、每轮 30 s，**近 400 秒**才能收敛——期间 A 与 B 之间形成转发环路，去往 N 的分组在两者之间来回踢皮球。\n\n## （3）解决措施\n① **水平分割（split horizon）**：路由器不会把从某个接口学来的路由再从该接口通告回去（B 不再向 A 通告到 N 的路由），可直接切断本例的环路；\n② **毒性逆转（poison reverse）**：比水平分割更强，B 不但不通告，反而向 A 通告"到 N 距离 = 16（不可达）"，让 A 立刻放弃该路由；\n③ **触发更新（triggered update）**：拓扑一变化立即发送更新，不等 30 s 周期，把环路蔓延的时间窗口压到最小；\n④ **抑制计时器（hold-down）**：收到某路由不可达后，一段时间内拒绝关于它的"更好消息"，防止过时路由被重新采用；\n⑤ **限制最大跳数 15**：使计数到无穷有上界（16 即不可达），代价是 RIP 只能用于小网络。\n\n## （4）OSPF 为何不受影响\nOSPF 是**链路状态**协议：每台路由器洪泛 LSA，使全网维护**一致的链路状态数据库（完整拓扑图）**，再各自用 Dijkstra 计算最短路径树。由于每个路由器都掌握了全局拓扑，链路断开后重新计算即可立即得到正确结果，**不存在"听信邻居"导致的环路**，收敛时间为秒级；此外 OSPF 以带宽为代价度量、支持 CIDR、区域划分与认证，适合中大型网络。',
'[{"point":"正确给出稳定状态下 C=1、B=2、A=3 的距离","score":3},{"point":"正确描述链路断开后 B 误信 A 的路由，距离 4→5→…→16 逐轮增大形成环路的计数到无穷过程","score":4},{"point":"给出至少三种解决措施（水平分割、毒性逆转、触发更新、抑制计时、最大跳数 15）并说明原理","score":3},{"point":"说明 OSPF 为链路状态协议，全网同步拓扑图后用 Dijkstra 计算，故不产生计数到无穷","score":2}]',12),

(43,'考研408',4,'case','某采用 CSMA/CD 的以太网：带宽 100 Mb/s，总线上相距最远的两台主机之间的**单向**传播时延 τ = 2.5 μs（忽略中继器与网卡延迟）。\n\n请回答：\n（1）争用期（冲突窗口）是多少？\n（2）为保证"发送完之前一定能检测到冲突"，最短帧长至少是多少字节？以太网实际规定的最短帧长是多少？\n（3）若某站点要发送 100 字节的帧和 40 字节的帧，分别能否在发送完毕前检测到最坏情况下的冲突？40 字节的帧该怎么办？\n（4）若把带宽提高到 1 Gb/s 而 τ 不变，最短帧长变为多少？千兆以太网是如何解决这一问题的？\n（5）冲突后站点采用什么退避算法？',
'[]','',
'解题路径是先算争用期 2τ（最坏情况：A 发出的信号刚要到达 B 的瞬间 B 才开始发送，冲突信号返回 A 需要再走一个 τ），再用"最短帧长 = 带宽 × 争用期"换算。关键点在于：帧的发送时延必须不小于争用期，否则站点在冲突信号返回之前就已经发完，会误以为发送成功。',
'## （1）争用期\n最坏情况下，A 的信号即将到达 B 时 B 才开始发送，冲突信号再经过 τ 传回 A，故**争用期 = 2τ = 5 μs**。\n\n## （2）最短帧长\n最短帧长 = 带宽 × 争用期 = 100 × 10⁶ b/s × 5 × 10⁻⁶ s = **500 bit = 62.5 字节**。\n以太网实际规定最短帧长为 **64 字节（512 bit）**（向上取整到便于硬件实现的字节数，并留有余量）。\n\n## （3）两个帧的判定\n- **100 字节帧**：发送时延 = (100 × 8) / 10⁸ = **8 μs > 5 μs**，发送完之前冲突信号一定已经返回，**能检测到冲突**；\n- **40 字节帧**：发送时延 = 320 / 10⁸ = **3.2 μs < 5 μs**，可能帧已发完冲突信号才回来，站点会误判发送成功，**不能可靠检测冲突**。\n处理：把帧**填充（padding）到 64 字节**再发送；接收端按长度字段/上层协议识别有效数据，忽略填充部分。\n\n## （4）带宽提升到 1 Gb/s\n最短帧长 = 10⁹ × 5 × 10⁻⁶ = **5000 bit = 625 字节**。若仍用 64 字节（发送时延仅 0.512 μs），冲突检测完全失效。\n千兆以太网的两条对策：\n① **载波延伸（carrier extension）**：把短帧的发送时间用填充扩展至相当于 512 字节的时长，使争用期约束重新成立（代价是短帧开销变大）；\n② **帧突发（frame bursting）**：一次获得信道后连续发送多个帧、只在首帧做载波延伸，把开销摊薄，提高有效吞吐率。\n\n## （5）二进制指数退避（截断）\n1. 取 k = min(重传次数, 10)；\n2. 从 {0, 1, ..., 2ᵏ − 1} 中随机取整数 r；\n3. 退避等待 **r × 51.2 μs**（51.2 μs 即 10 Mb/s 以太网的一个争用期，作为基本退避时间）；\n4. 重传 16 次仍失败则丢弃该帧并向上层报告。\n随着重传次数增多，随机窗口指数增大，冲突概率随之下降，算法在负载与延迟之间取得平衡。',
'[{"point":"正确算出争用期 2τ = 5 μs","score":2},{"point":"正确算出最短帧长 500 bit（62.5 字节）并指出以太网实际取 64 字节","score":3},{"point":"正确判断 100 字节帧（8 μs）可检测到冲突、40 字节帧（3.2 μs）不行需填充到 64 字节","score":3},{"point":"说明 1 Gb/s 时最短帧长变为 625 字节，千兆以太网用载波延伸与帧突发解决","score":2},{"point":"说明二进制指数退避：k=min(重传次数,10)，随机取 r∈[0,2^k-1]，退避 r×51.2 μs，16 次失败丢弃","score":2}]',12),

(45,'考研408',4,'case','一个 IP 数据报的总长度为 4020 字节（其中固定首部 20 字节，无选项字段，数据部分 4000 字节，标识字段 Identification = 12345，DF = 0），要经过一条 MTU = 1500 字节的链路。\n\n请回答：\n（1）该数据报应被分成几片？每片的数据长度、总长度字段、片偏移字段与 MF 标志分别是多少？\n（2）为什么除最后一片外，每片的数据长度必须是 8 的整数倍？\n（3）各片的标识字段是否相同？目的主机依据什么把分片还原成原始数据报？\n（4）若该数据报的 DF 标志为 1，路由器会怎么做？IPv6 在分片策略上有什么不同？',
'[]','',
'解题路径是"数据部分按 8 字节为单位切分"：先扣除 20 字节首部得到每片数据上限 1480 字节，再向下取整到 8 的倍数（1480 = 8 × 185 恰好满足），于是 4000 = 1480 + 1480 + 1040；片偏移以 8 字节为单位计数，故三片偏移分别为 0、185、370；除最后一片外 MF = 1。',
'## （1）分片结果\n每片数据部分上限 = MTU − 首部 = 1500 − 20 = **1480 字节**（且必须是 8 的倍数）。\n4000 = 1480 + 1480 + 1040，共 **3 片**：\n\n| 分片 | 数据长度 | 总长度字段 | 片偏移 | MF | DF |\n|---|---|---|---|---|---|\n| 第 1 片 | 1480 B | 1500 | **0** | 1 | 0 |\n| 第 2 片 | 1480 B | 1500 | **185** | 1 | 0 |\n| 第 3 片 | 1040 B | **1060** | **370** | **0** | 0 |\n\n校验：片偏移 × 8 = 字节偏移，185 × 8 = 1480，370 × 8 = 2960，2960 + 1040 = 4000 ✔\n\n## （2）8 的整数倍的原因\n片偏移字段只有 **13 bit**，无法以字节为单位表示长达 65535 的偏移，因此规定片偏移的单位是 **8 字节**；相应地，除最后一片外每片的数据长度必须是 8 的整数倍，否则下一片的字节偏移无法用"整数 × 8"表示。\n\n## （3）标识与重组\n三片的 **Identification 均为 12345**（从原始数据报复制），MF 与片偏移各自不同。\n目的主机的重组依据：**源 IP 地址 + 目的 IP 地址 + 协议字段 + 标识** 共同确定"这些分片属于同一个数据报"，再按片偏移排序拼接，见到 MF = 0 的分片即可算出原始数据报总长度。超时未集齐则丢弃全部（防止半截数据被交付）。\n\n## （4）DF = 1 与 IPv6 的差异\n- **DF = 1（不分片）**：路由器不能分片，只能**丢弃**该数据报，并向源主机发送 **ICMP 目的不可达（Type 3, Code 4：需要分片但 DF 置位）**。这正是一条链路上发现 MTU 变小的机制，也是路径 MTU 发现（PMTUD）的基础；源端收到后应调小报文长度重发（本例可改为 ≤ 1480 字节的数据）。\n- **IPv6**：中间路由器**不再分片**，只向源发 ICMPv6 "Packet Too Big"；分片只允许由**源主机**用分片扩展首部完成，把复杂度从路由器移到端系统，提高了转发效率。',
'[{"point":"正确算出每片数据上限 1480 字节，并给出三片的数据长度 1480/1480/1040 与总长度 1500/1500/1060","score":3},{"point":"正确给出片偏移 0/185/370 与 MF = 1/1/0","score":3},{"point":"说明片偏移字段以 8 字节为单位，故除最后一片外数据长度必须是 8 的整数倍","score":3},{"point":"说明各片标识字段相同、重组在目的主机按标识与片偏移完成；DF=1 时路由器丢弃并回 ICMP Type 3 Code 4，IPv6 只允许源主机分片","score":3}]',12);
