INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(41,'NCRE',3,'programming','**编写程序计算子网信息并判断 IP 归属**\n\n输入格式：两行。\n- 第一行：一个 CIDR 地址块，形如 `192.168.10.64/26`；\n- 第二行：一个待判断的 IP 地址，形如 `192.168.10.70`。\n\n输出格式：五行，依次为\n```\n掩码: <点分十进制>\n网络地址: <点分十进制>\n广播地址: <点分十进制>\n可用主机范围: <首地址> - <末地址>\n<IP> 属于该网络: YES 或 NO\n```\n\n要求：\n1. 用 Python 3 写出完整可运行程序（不得使用 `ipaddress` 等现成库，须自己用位运算实现）；\n2. 正确生成掩码（含 /0 的情况），并区分 /31、/32 两种特殊前缀；\n3. 判断 IP 是否属于该网络时须用 `(ip & mask) == net` 而不是字符串比较。',
'[]','',
'解题路径是把点分十进制转成 32 位整数再做位运算：掩码由前缀长度 p 生成（高 p 位为 1，注意 p = 0 时左移 32 位在部分语言里未定义，需特判）；网络地址 = IP & 掩码；广播地址 = 网络地址 | (掩码取反)；可用主机数 = 2^(32−p) − 2。关键点在于全部运算都在整数域进行，且判断归属时用按位与的结果与网络地址比较，避免逐段字符串比较带来的边界错误。',
'## 思路\n1. `ip2int`：四段各自左移 24/16/8/0 位后按位或；`int2ip`：逐段取 8 位还原；\n2. `mask = (0xFFFFFFFF << (32 - p)) & 0xFFFFFFFF`，p = 0 时直接取 0；\n3. `net = ip & mask`，`bcast = net | (~mask & 0xFFFFFFFF)`；\n4. 可用主机：p ≤ 30 时为 `net+1 ~ bcast-1`；p = 31 为点对点链路，两端都可用；p = 32 为主机路由，仅 1 个地址；\n5. 归属判断：`(host & mask) == net`。\n\n## 参考程序（Python 3）\n```python\nimport sys\n\n\ndef ip2int(ip):\n    a, b, c, d = (int(x) for x in ip.split("."))\n    return (a << 24) | (b << 16) | (c << 8) | d\n\n\ndef int2ip(n):\n    return "%d.%d.%d.%d" % ((n >> 24) & 255, (n >> 16) & 255, (n >> 8) & 255, n & 255)\n\n\ndef make_mask(p):\n    if p <= 0:\n        return 0\n    return (0xFFFFFFFF << (32 - p)) & 0xFFFFFFFF\n\n\ndef main():\n    data = sys.stdin.read().split()\n    if len(data) < 2:\n        return\n    cidr, host = data[0], data[1]\n    ip_str, p_str = cidr.split("/")\n    p = int(p_str)\n    mask = make_mask(p)\n    net = ip2int(ip_str) & mask\n    bcast = net | (mask ^ 0xFFFFFFFF)\n\n    print("掩码: %s" % int2ip(mask))\n    print("网络地址: %s" % int2ip(net))\n    print("广播地址: %s" % int2ip(bcast))\n\n    if p <= 30:\n        print("可用主机范围: %s - %s" % (int2ip(net + 1), int2ip(bcast - 1)))\n    elif p == 31:\n        print("可用主机范围: %s - %s" % (int2ip(net), int2ip(bcast)))\n    else:\n        print("可用主机范围: %s" % int2ip(net))\n\n    print("%s 属于该网络: %s" % (host, "YES" if (ip2int(host) & mask) == net else "NO"))\n\n\nif __name__ == "__main__":\n    main()\n```\n\n## 运行示例\n输入：\n```\n192.168.10.64/26\n192.168.10.70\n```\n输出：\n```\n掩码: 255.255.255.192\n网络地址: 192.168.10.64\n广播地址: 192.168.10.127\n可用主机范围: 192.168.10.65 - 192.168.10.126\n192.168.10.70 属于该网络: YES\n```\n再如输入 `10.0.0.5/8` 与 `10.255.255.255` → 网络地址 10.0.0.0、广播 10.255.255.255、属于该网络 YES；输入 `192.168.10.64/26` 与 `192.168.10.130` → NO（130 落在下一个子网 192.168.10.128/26）。',
'[{"point":"正确实现点分十进制与 32 位整数的互相转换（移位与按位或/按位与）","score":3},{"point":"正确由前缀长度生成掩码，并对 /0（以及不使用左移 32 位的未定义行为）做特判","score":3},{"point":"正确算出网络地址（IP & 掩码）与广播地址（网络地址 | 掩码取反）","score":3},{"point":"正确输出可用主机范围与主机数，并区分 /31 点对点链路与 /32 主机路由","score":3},{"point":"判断 IP 归属时使用 (ip & mask) == net 的按位比较，程序可运行且输入输出格式一致","score":3}]',15);

