INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(48,'NCRE',4,'programming','**银行家算法：安全性检查**\n\n输入格式：\n```\nn m\ntotal_1 total_2 ... total_m\n<接下来 n 行：第 i 行为进程 Pi 的 Max 矩阵行，m 个整数>\n<接下来 n 行：第 i 行为进程 Pi 的 Allocation 矩阵行，m 个整数>\n```\n其中 total 为各类资源的总量，进程编号从 P0 开始。\n\n输出格式：\n- 若系统安全：第一行输出 `SAFE`，第二行输出一个安全序列（进程名用空格分隔，如 `P1 P3 P4 P0 P2`）；\n- 若不安全：输出一行 `UNSAFE`。\n\n要求：用 Python 3 写出完整程序（含输入输出处理），先由 total 与 Allocation 计算 Available 向量，再由 Max 与 Allocation 计算 Need 矩阵，最后执行安全性算法。',
'[]','',
'解题路径是标准的银行家算法安全性检查：Work 初始化为 Available，反复扫描所有未完成进程，找到 Need ≤ Work 的进程就假定它运行完毕、把它的 Allocation 全部归还到 Work 并记入序列；若一轮扫描找不到任何可满足的进程而仍有进程未完成，则系统不安全。关键点在于"归还资源"这一步——只有把已分配资源加回 Work，后面的进程才可能满足条件。',
'## 思路\n1. `avail[j] = total[j] − Σ_i alloc[i][j]`；`need[i][j] = max[i][j] − alloc[i][j]`；\n2. `finish = [False] * n`，`seq = []`；\n3. 反复扫描：对每个未完成进程 i，若对所有 j 都有 `need[i][j] <= work[j]`，则 `work[j] += alloc[i][j]`，置 finish[i] = True 并把 i 加入 seq；\n4. 若某轮扫描没有任何进程可满足 → 提前结束；最终 `len(seq) == n` 即安全。\n\n## 参考程序（Python 3）\n```python\nimport sys\n\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    n = int(data[idx])\n    idx += 1\n    m = int(data[idx])\n    idx += 1\n    total = [int(data[idx + k]) for k in range(m)]\n    idx += m\n\n    max_claim = []\n    for _ in range(n):\n        max_claim.append([int(data[idx + k]) for k in range(m)])\n        idx += m\n    alloc = []\n    for _ in range(n):\n        alloc.append([int(data[idx + k]) for k in range(m)])\n        idx += m\n\n    need = [[max_claim[i][j] - alloc[i][j] for j in range(m)] for i in range(n)]\n    work = [total[j] - sum(alloc[i][j] for i in range(n)) for j in range(m)]\n    finish = [False] * n\n    seq = []\n\n    while len(seq) < n:\n        found = False\n        for i in range(n):\n            if finish[i]:\n                continue\n            if all(need[i][j] <= work[j] for j in range(m)):\n                for j in range(m):\n                    work[j] += alloc[i][j]\n                finish[i] = True\n                seq.append(i)\n                found = True\n        if not found:\n            break\n\n    if len(seq) == n:\n        print("SAFE")\n        print(" ".join("P%d" % i for i in seq))\n    else:\n        print("UNSAFE")\n\n\nif __name__ == "__main__":\n    main()\n```\n\n## 运行示例\n输入：\n```\n5 3\n10 5 7\n7 5 3\n3 2 2\n9 0 2\n2 2 2\n4 3 3\n0 1 0\n2 0 0\n3 0 2\n2 1 1\n0 0 2\n```\n输出：\n```\nSAFE\nP1 P3 P4 P0 P2\n```\n（可用向量 Available = (10,5,7) − (7,2,5) = (3,3,2)，与手算一致。）\n\n复杂度：每轮扫描 O(n·m)，最多 n 轮，故为 O(n²·m)。注意安全序列不一定唯一，任何合法序列都应判为 SAFE。',
'[{"point":"正确读入数据并计算 Need 矩阵（Max−Allocation）与 Available 向量（总量−已分配之和）","score":4},{"point":"正确实现安全性算法的主体：反复查找 Need ≤ Work 的未完成进程","score":5},{"point":"进程完成时把其 Allocation 全部归还 Work，并置 finish 标记、记入序列","score":3},{"point":"正确处理找不到可满足进程的情况并输出 SAFE/安全序列 或 UNSAFE","score":2},{"point":"程序完整可运行（含 main、输入解析、输出格式与示例验证）","score":2},{"point":"说明复杂度 O(n²m) 以及安全序列不唯一等性质","score":2}]',18),

(16,'NCRE',3,'programming','**LRU 页面置换算法模拟**\n\n输入格式：\n- 第一行两个整数 m n，m 为分配给进程的物理块数（1 ≤ m ≤ 10），n 为页面访问次数（1 ≤ n ≤ 1000）；\n- 第二行 n 个整数，为页面引用串。\n\n输出格式：两行\n```\n缺页次数: <整数>\n缺页率: <百分数，保留两位小数，带百分号>\n```\n\n要求：用 Python 3 写出完整程序（含 main），用列表维护内存中的页面（越靠后表示越近被使用），**命中时**把该页移到列表末尾，**缺页且内存已满时**淘汰列表头部（最久未使用）的页面。',
'[]','',
'解题路径是维护一个"按最近使用时间排序"的列表：命中就把该页移到队尾表示刚被使用；缺页时若内存未满直接装入，已满则淘汰队首（最久未使用）再装入。关键点在于命中也要更新顺序——只淘汰不更新会把"刚刚访问过的页"错误地当成最久未使用。',
'## 思路\n用一个列表 `mem` 表示内存中的页，`mem[0]` 最久未使用、`mem[-1]` 最近使用：\n1. 访问页 p：若 `p in mem`，把它删除再 append 到末尾（命中，更新使用序）；\n2. 否则缺页计数加一：`len(mem) == m` 时 `mem.pop(0)`，然后 `mem.append(p)`；\n3. 缺页率 = 缺页次数 / n × 100%。\n\n## 参考程序（Python 3）\n```python\nimport sys\n\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    pages = [int(x) for x in data[2:2 + n]]\n\n    mem = []            # mem[0] 最久未使用，mem[-1] 最近使用\n    faults = 0\n    for p in pages:\n        if p in mem:\n            mem.remove(p)\n            mem.append(p)   # 命中：更新为最近使用\n        else:\n            faults += 1\n            if len(mem) == m:\n                mem.pop(0)  # 淘汰最久未使用\n            mem.append(p)\n\n    rate = faults * 100.0 / n if n > 0 else 0.0\n    print("缺页次数: %d" % faults)\n    print("缺页率: %.2f%%" % rate)\n\n\nif __name__ == "__main__":\n    main()\n```\n\n## 运行示例\n输入：\n```\n3 20\n7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1\n```\n输出：\n```\n缺页次数: 12\n缺页率: 60.00%\n```\n（与手工模拟的 LRU 结果一致；物理块数为 4 时缺页次数会进一步下降，因为 LRU 具有栈特性，不会出现 Belady 异常。）\n\n复杂度：列表查找为 O(m)，m ≤ 10 时完全够用；若 m 很大可改用哈希表 + 双向链表实现 O(1) 的 get/put（即 LRU 缓存的经典写法）。',
'[{"point":"正确用列表维护内存页面，并保证命中时把该页移到末尾更新使用顺序","score":5},{"point":"缺页且内存已满时淘汰列表头部（最久未使用）的页面","score":3},{"point":"正确统计缺页次数并计算缺页率（保留两位小数并带百分号）","score":3},{"point":"正确处理内存未满时不淘汰、以及 n=0 等边界情况","score":2},{"point":"程序完整可运行（含 main、输入解析、输出格式与示例验证）","score":2}]',15);
