--  C 语言程序设计（course 10）
-- ============================================================
INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(70,'软考',4,'case','下面是某同学写的 C 程序，运行后可能出现乱码、崩溃，且长期运行会占用内存越来越多。请分析并改错。\n\n```c\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *dup(const char *s) {\n    char *p = (char *)malloc(strlen(s));      /* ① */\n    strcpy(p, s);                             /* ② */\n    return p;\n}\n\nint main(void) {\n    char *a = dup("hello");\n    char *b = a;\n    printf("%s\\n", a);\n    free(a);\n    printf("%s\\n", b);                        /* ③ */\n    b = dup(b);                               /* ④ */\n    printf("%s\\n", b);\n    return 0;                                 /* ⑤ */\n}\n```\n\n请回答：\n（1）逐条指出 ① ~ ⑤ 处存在的问题及后果；\n（2）给出修正后的完整代码；\n（3）总结动态内存使用的若干条铁律。',
'[]','',
'解题路径是逐行审查每一处内存操作：① 分配空间是否足够（字符串结尾的 0 也要占一字节）；② 拷贝是否有长度上限；③ 释放之后的指针是否还被使用；④ 是否把已释放指针再次传入函数；⑤ 分配的空间是否都有对应的释放。关键点在于"释放"只是把内存归还给堆管理器，指针变量本身的值不变，因此必须手动置空才能杜绝误用。',
'## （1）逐条问题\n- **①**：`malloc(strlen(s))` 只分配了字符串长度个字节，**没有给结尾的 `0` 留位置**，应为 `strlen(s) + 1`。\n- **②**：紧接着的 `strcpy` 会把 6 个字节（含 `0`）写进只有 5 字节的堆块，造成**堆缓冲区溢出（越界写 1 字节）**，可能破坏堆管理元数据，在 `free` 或后续分配时崩溃；且 `strcpy` 本身不检查长度；另外这里**没有检查 malloc 是否返回 NULL**。\n- **③**：`free(a)` 之后 `a` 与 `b` 指向的内存已被归还，`b` 成为**悬垂指针（dangling pointer）**，再用 `%s` 读取它是**未定义行为**（可能打印乱码，也可能直接崩溃）。\n- **④**：把已经释放的指针 `b` 传给 `dup`，函数内部的 `strlen(b)` 会再次读取已释放内存，仍是未定义行为。\n- **⑤**：`b` 指向的新内存**从未释放**，函数返回前也没有 `free`，造成**内存泄漏**；在长期运行的服务器程序中会不断累积。\n\n## （2）修正后的代码\n```c\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *dup(const char *s) {\n    if (s == NULL) return NULL;\n    size_t n = strlen(s) + 1;          /* 记得为结尾的 0 多分配一个字节 */\n    char *p = (char *)malloc(n);\n    if (p == NULL) return NULL;        /* 必须检查分配是否成功 */\n    memcpy(p, s, n);                   /* 长度已知，memcpy 比 strcpy 更安全 */\n    return p;\n}\n\nint main(void) {\n    char *a = dup("hello");\n    if (a == NULL) return 1;\n    printf("%s\\n", a);\n\n    free(a);\n    a = NULL;                          /* 释放后立即置空，杜绝悬垂指针 */\n\n    char *b = dup("world");            /* 重新分配，不再使用已释放的指针 */\n    if (b == NULL) return 1;\n    printf("%s\\n", b);\n\n    free(b);\n    b = NULL;                          /* 谁分配谁释放，成对出现 */\n    return 0;\n}\n```\n\n## （3）动态内存铁律\n1. `malloc/calloc/realloc` 之后**必须检查返回值**是否为 NULL；\n2. 分配字符串时为结尾的 `0` **多分配 1 字节**，拷贝一律使用带长度上限的 `memcpy/strncpy/snprintf`；\n3. **谁分配谁释放**，每个 `malloc` 都要有且仅有一个对应的 `free`；\n4. `free` 之后**立即把指针置为 NULL**（对 NULL 调用 free 是安全的，对悬垂指针调用 free 是双重释放）；\n5. 不返回、不保存指向已释放内存的指针；同一块内存绝不 `free` 两次；\n6. 排查工具：AddressSanitizer（`-fsanitize=address`）、Valgrind，能在运行期直接报出越界、泄漏与 UAF（use-after-free）。',
'[{"point":"指出 malloc(strlen(s)) 少分配 1 字节导致 strcpy 写越界（堆溢出），应为 strlen(s)+1","score":3},{"point":"指出 free(a) 后 b 成为悬垂指针，读取它属于未定义行为","score":3},{"point":"指出把已释放指针再次传入 dup 是未定义行为，且最后未 free(b) 造成内存泄漏","score":3},{"point":"给出修正代码：分配 strlen+1、检查 NULL、释放后置空、配对释放，并总结动态内存使用铁律","score":3}]',12),

(67,'期末',3,'case','下面是某同学写的 C 程序，请分析其运行结果的正确性并说明原因。\n\n```c\n#include <stdio.h>\n\nchar *getName(void) {\n    char buf[32];\n    scanf("%31s", buf);\n    return buf;              /* ① */\n}\n\nint *getPtr(void) {\n    int x = 10;\n    return &x;               /* ② */\n}\n\nlong long fact(int n) {\n    if (n == 0) return 1;\n    return (long long)n * fact(n - 1);   /* ③ */\n}\n\nint main(void) {\n    char *name = getName();\n    printf("%s\\n", name);\n    printf("%d\\n", *getPtr());\n    printf("%lld\\n", fact(100000));      /* ④ */\n    return 0;\n}\n```\n\n请回答：\n（1）① 和 ② 返回的是什么？程序运行结果是否正确？为什么？\n（2）给出三种可行的修改方案并比较其优劣；\n（3）③ 的递归调用在栈帧中保存了什么？④ 会出现什么问题？如何改写？\n（4）简述函数调用时栈帧的建立与撤销过程，以及栈的生长方向。',
'[]','',
'解题路径是区分"变量的存储期"：局部自动变量存放在栈帧里，函数返回时栈帧被撤销（栈指针回退，内存内容不再受保护，随时会被下一次调用的栈帧覆盖），因此返回它们的地址得到的必然是悬垂指针。关键点在于理解栈帧里到底存了什么、以及递归深度与栈容量之间的关系。',
'## （1）① 与 ② 的问题\n两者都返回了**局部自动变量（栈上变量）的地址**：\n- ① 返回局部数组 `buf` 的首地址；\n- ② 返回局部变量 `x` 的地址。\n函数返回后其栈帧被撤销，虽然栈指针回退后内存中的"旧值"可能还在，但这块内存随时会被后续的函数调用（本例中紧随其后的 `printf`）覆盖。因此 `printf("%s\\n", name)` 可能打印乱码、空串，也可能侥幸打印出正确内容；`*getPtr()` 同理。这属于**未定义行为**，编译时应开启 `-Wall` 会得到 "function returns address of local variable" 警告。\n\n## （2）三种修改方案\n① **由调用者提供缓冲区**（推荐）：\n```c\nvoid getName(char *buf, size_t n) {\n    if (n > 0) { scanf("%31s", buf); buf[n - 1] = 0; }\n}\n```\n优点：内存由调用者管理，无泄漏、可重入、线程安全；缺点：接口稍繁琐。\n② **返回 static 局部变量**：\n```c\nchar *getName(void) {\n    static char buf[32];\n    scanf("%31s", buf);\n    return buf;\n}\n```\n优点：写法最简单；缺点：位于静态存储区，**不可重入、非线程安全**，多次调用会覆盖上一次结果，多线程或递归调用时会出错。\n③ **malloc 分配、调用者 free**：\n```c\nchar *getName(void) {\n    char *p = (char *)malloc(32);\n    if (p) scanf("%31s", p);\n    return p;   /* 调用者用完必须 free */\n}\n```\n优点：灵活、可返回任意长度、线程安全；缺点：调用者必须记得释放，容易泄漏。\n\n## （3）递归与栈溢出\n每次递归调用都会在栈上建立一个新的**栈帧**，其中保存：函数实参、返回地址、调用者的帧指针（EBP/RBP）、被调用者保存的寄存器、以及本次调用的局部变量（如 `n`）。\n`fact(100000)` 的递归深度为 10 万层，而默认栈空间有限（Linux 主线程通常 8 MB，单帧按几十字节算也只能支撑几万层），因此会发生**栈溢出（stack overflow）**，表现为段错误（SIGSEGV）。此外 100000! 早已超出 `long long` 的表示范围，结果必然溢出（即便改成迭代也一样）。\n**改写为迭代**：\n```c\nlong long fact(int n) {\n    long long r = 1;\n    for (int i = 2; i <= n; i++) r *= i;\n    return r;\n}\n```\n迭代消除了栈溢出风险，也更快（无函数调用开销）。另外可在关键位置加深度上限检查，或改用尾递归（依赖编译器优化）。\n\n## （4）栈帧的建立与撤销\n- **调用时（建立）**：把实参按约定压栈或放入寄存器 → 执行 call 指令，把**返回地址**压栈 → 被调函数把调用者的帧指针压栈并建立自己的帧指针 → 为局部变量开辟空间（栈指针下移）。\n- **返回时（撤销）**：把返回值放入约定寄存器 → 恢复帧指针与栈指针（局部变量空间被"释放"）→ ret 弹出返回地址跳回调用者 → 调用者清理实参。\n- 栈通常**向低地址方向生长**（栈指针减小即为分配空间），堆则向高地址生长；栈由编译器自动管理，速度快但容量有限。',
'[{"point":"指出 ①② 返回局部自动变量（栈上）地址，函数返回后栈帧失效，结果属于未定义行为","score":4},{"point":"给出三种修改方案（调用者提供缓冲区 / static / malloc）并比较线程安全与可重入性","score":3},{"point":"说明递归栈帧中保存实参、返回地址、帧指针与局部变量，且 fact(100000) 会导致栈溢出","score":3},{"point":"说明栈帧建立与撤销过程、栈向低地址生长及容量有限，并给出迭代改写","score":2}]',12);
-- ---------- 结构体对齐 / 数组越界 ----------
INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(68,'NCRE',3,'case','在 64 位 Linux + GCC（默认对齐，各类型自身大小：char 1、short 2、int 4、double 8）环境下，定义如下四个结构体：\n\n```c\nstruct A { char c; int i; short s; };\nstruct B { int i; char c; short s; };\nstruct C { double d; char c; };\nstruct D { char a; double d; int b; };\n```\n\n请回答：\n（1）分别计算 sizeof(struct A) ~ sizeof(struct D) 的值，并画出各自的成员布局（偏移）；\n（2）若在文件开头加上 `#pragma pack(1)`，四个值分别变为多少？\n（3）简述内存对齐的两条规则；\n（4）为什么要做内存对齐？什么场景下反而要**取消**对齐？',
'[]','',
'解题路径是按"成员按自身对齐值对齐、结构体总大小按最大对齐值补齐"两条规则逐成员摆放：先看该成员需要的对齐数 k，把偏移向上取整到 k 的倍数，放完后再检查总大小是否为最大对齐值的倍数。关键点在于把成员**按对齐数从大到小排列**通常能最省空间，本题 A 与 B 成员相同但顺序不同，大小却差了 4 字节。',
'## （1）默认对齐下的布局与大小\n**struct A**：c 在 0（占 1），i 需 4 字节对齐 → 偏移补到 **4**，占 4~7；s 需 2 字节对齐 → 放在 **8**，占 8~9；总大小目前 10，最大对齐值 4，补齐到 **12**。\n→ `sizeof(struct A) = 12`（中间浪费 3 字节，尾部浪费 2 字节）\n\n**struct B**：i 在 0~3；c 在 **4**；s 需 2 字节对齐 → 偏移补到 **6**，占 6~7；总大小 8，已是 4 的倍数。\n→ `sizeof(struct B) = 8`（把大对齐成员放前面，省了 4 字节）\n\n**struct C**：d 在 0~7；c 在 **8**；总大小 9，最大对齐值 8，补齐到 **16**。\n→ `sizeof(struct C) = 16`\n\n**struct D**：a 在 0；d 需 8 字节对齐 → 偏移补到 **8**，占 8~15；b 在 **16**，占 16~19；总大小 20，最大对齐值 8，补齐到 **24**。\n→ `sizeof(struct D) = 24`\n\n## （2）#pragma pack(1)\n按 1 字节对齐，成员紧密排列、无填充：\n- A = 1 + 4 + 2 = **7**\n- B = 4 + 1 + 2 = **7**\n- C = 8 + 1 = **9**\n- D = 1 + 8 + 4 = **13**\n\n## （3）对齐规则\n① **成员偏移规则**：每个成员相对结构体首地址的偏移量，必须是 `min(该成员自身对齐值, 编译器指定对齐值)` 的整数倍；数组按元素类型的对齐值算，嵌套结构体按其内部最大成员的对齐值算。\n② **整体补齐规则**：结构体的总大小必须是**所有成员中最大对齐值**的整数倍，不足则在末尾填充。\n\n## （4）为什么对齐，以及何时取消\n**为什么**：CPU 访问内存以字长/总线宽度为单位，若数据跨越了两个访问单元，就需要**多次访存再拼接**，性能下降；在部分架构（如早期 ARM、某些 RISC 处理器）上未对齐访问还会直接触发**对齐异常**甚至崩溃。因此对齐是典型的"以空间换时间"。\n**何时取消**：\n- 网络报文、文件格式、硬件寄存器映射等**跨平台的二进制布局**必须严格紧凑，此时用 `#pragma pack(1)` 或 `__attribute__((packed))`，保证各编译器布局一致（同时还要注意**大小端**问题）；\n- 内存极度紧张、且访问很频繁的嵌入式场景；\n- 代价是可能引入未对齐访问的性能损失甚至异常，因此工程上更推荐"内存里保持对齐、序列化时按字节打包"的做法。',
'[{"point":"正确算出 struct A = 12 且 struct B = 8，并给出成员偏移布局","score":3},{"point":"正确算出 struct C = 16 且 struct D = 24（尾部按最大对齐值补齐）","score":3},{"point":"正确给出 #pragma pack(1) 下的四个值 7 / 7 / 9 / 13","score":2},{"point":"说明对齐的两条规则（成员偏移按对齐值取整、整体按最大对齐值补齐），并说明未对齐访问需多次访存甚至异常、二进制协议场景需取消对齐","score":2}]',10),

(69,'软考',4,'case','下面是某同学写的 C 程序，请逐条分析其中存在的问题、可能的后果，并给出修正方案。\n\n```c\n#include <stdio.h>\n#include <string.h>\n\nvoid foo(const char *input) {\n    char buf[8];\n    strcpy(buf, input);         /* ① */\n    printf("%s\\n", buf);\n}\n\nint main(void) {\n    foo("0123456789abcdef");    /* ② */\n    char *s = "hello";\n    s[0] = 72;                  /* ③ 72 是大写字母 H */\n    int a[5] = {1, 2, 3, 4, 5};\n    printf("%d\\n", a[5]);       /* ④ */\n    return 0;\n}\n```\n\n请回答：\n（1）① 与 ② 组合会产生什么后果？为什么？\n（2）③ 为什么可能崩溃？如何修改？\n（3）④ 的访问有何问题？\n（4）给出修正后的安全写法，并说明编译期与运行期有哪些防护手段。',
'[]','',
'解题路径是逐条检查"写操作的目标空间是否足够、是否可写、下标是否合法"：strcpy 不检查目标容量，外部输入直接拷进 8 字节栈数组必然越界；字符串字面量位于只读段，写入会触发段错误；C 语言不做下标检查，越界读到的内容完全不确定。关键点在于缓冲区溢出不仅会崩溃，还可能覆盖返回地址而被恶意利用。',
'## （1）① + ②：栈缓冲区溢出\n`buf` 只有 8 字节，而 `"0123456789abcdef"` 有 16 个字符、加结尾的 0 共 **17 字节**；`strcpy` **完全不检查目标容量**，会一路往下写，覆盖 `buf` 之后的栈空间——首先是调用者的帧指针，接着是**函数返回地址**。\n后果：\n- 轻则程序崩溃（段错误），栈上的其它局部变量被莫名改写；\n- 重则被攻击者利用：精心构造的输入可以**覆盖返回地址**，使函数返回时跳转到攻击者指定的代码（经典的栈溢出攻击，配合 ROP/return-to-libc 可绕过防护执行任意代码）。\n\n## （2）③：修改字符串字面量\n`char *s = "hello";` 中的 `"hello"` 是**字符串字面量**，存放在只读数据段（`.rodata`），由操作系统的页表属性保护。执行 `s[0] = 72` 试图写只读页，会触发**段错误（SIGSEGV）**。\n修改：\n```c\nchar s[] = "hello";   /* 在栈上创建一份可写的数组副本，内容初始化为 hello */\ns[0] = 72;            /* 合法 */\n```\n补充：即使把字面量赋给 `char *`（而非 `const char *`）在 C 中是允许的，也**绝不能**写入；建议一律写成 `const char *s = "hello";`，让编译器帮你发现错误。\n\n## （3）④：数组越界访问\n`int a[5]` 的合法下标是 **0 ~ 4**，`a[5]` 越界读了一个不存在的元素。C 语言**不做下标检查**（下标运算本质是 `*(a + 5)`），因此：\n- 读到的值是栈上相邻内存的"垃圾值"，结果不确定，且每次运行可能不同；\n- 若是越界**写**，则更为危险，可能破坏相邻变量、帧指针或返回地址；\n- 这类问题不会在编译期报错，只能靠程序员保证或使用工具检测。\n\n## （4）修正写法与防护手段\n```c\n#include <stdio.h>\n#include <string.h>\n\nvoid foo(const char *input) {\n    char buf[8];\n    /* snprintf 会按目标容量截断，并保证结尾有 0 */\n    snprintf(buf, sizeof buf, "%s", input);\n    printf("%s\\n", buf);\n}\n\nint main(void) {\n    foo("0123456789abcdef");   /* 安全：只写入 7 个字符 + 0 */\n    char s[] = "hello";\n    s[0] = 72;\n    int a[5] = {1, 2, 3, 4, 5};\n    for (int i = 0; i < 5; i++) printf("%d ", a[i]);\n    return 0;\n}\n```\n更一般的原则：一律使用带长度上限的 `snprintf / strncpy / memcpy / fgets`，**永远不要用 `gets`**；所有外部输入都要校验长度。\n\n**编译期防护**：`-Wall -Wextra` 打开警告；`-D_FORTIFY_SOURCE=2 -O2` 让编译器为 `strcpy/memcpy` 等插入长度检查；`-fstack-protector-strong` 插入**栈金丝雀（canary）**，函数返回前校验其是否被改写。\n**运行期防护**：ASLR（地址空间随机化）、NX/DEP（栈不可执行）、栈金丝雀；开发期用 AddressSanitizer（`-fsanitize=address`）或 Valgrind 直接定位越界与 UAF。',
'[{"point":"指出 strcpy 无长度检查、17 字节写入 8 字节数组造成栈缓冲区溢出，可能覆盖返回地址并被利用","score":4},{"point":"指出修改字符串字面量（只读段）会触发段错误，应改为 char s[] = hello 创建可写副本","score":3},{"point":"指出 a[5] 越界访问、C 不做下标检查且结果不确定","score":3},{"point":"给出修正写法（snprintf/fgets/strncpy 带长度上限）并说明编译期（-D_FORTIFY_SOURCE、stack-protector）与运行期（ASLR、NX/Canary）防护手段","score":2}]',12);

-- ---------- C 语言编程题 ----------
INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, reference_answer, grading_points, score) VALUES
(69,'NCRE',3,'programming','**安全的字符串拼接**\n\n输入格式：两行，每行一个不含空格的字符串（长度不超过 100）。\n输出格式：\n- 第一行：两行字符串拼接后的结果；\n- 第二行：`len=<拼接后长度>`。\n\n要求：\n1. 用 C99 写出完整程序（含 main 与必要头文件）；\n2. 自己实现 `int safe_cat(char *dst, size_t cap, const char *src)`：把 src 追加到 dst 末尾，**保证写入总长度不超过 cap（含结尾 0）**，成功返回 0，空间不足返回 −1 且不修改 dst；\n3. 严禁使用 `gets`，读行一律用 `fgets` 并去掉末尾换行符。',
'[]','',
'解题路径是先算出 dst 已用长度与 src 长度，判断 `used + need + 1 > cap` 就拒绝拼接（这里的 +1 是给结尾 0 留的位置），否则用 memcpy 按精确长度拷贝。关键点在于**先判断后写入**，且所有涉及字符串结尾 0 的计算都不能漏掉那一个字节——这正是 strcpy 类函数溢出的根因。',
'## 思路\n1. `used = strlen(dst)`，`need = strlen(src)`；\n2. 若 `used + need + 1 > cap` 返回 −1（容量要同时容纳已有内容、新内容和结尾的 0）；\n3. 否则 `memcpy(dst + used, src, need + 1)`（连结尾 0 一起拷过去）；\n4. 读行用 `fgets(line, sizeof line, stdin)`，再把末尾的换行符（ASCII 10）替换为 0——`gets` 无法限制长度，已被 C11 标准移除，绝不能使用。\n\n## 参考程序（C99）\n```c\n#include <stdio.h>\n#include <string.h>\n\n#define CAP 256\n\nstatic int safe_cat(char *dst, size_t cap, const char *src) {\n    size_t used = strlen(dst);\n    size_t need = strlen(src);\n    if (used + need + 1 > cap) return -1;      /* +1 留给结尾的 0 */\n    memcpy(dst + used, src, need + 1);\n    return 0;\n}\n\nstatic void trim_newline(char *s) {\n    size_t n = strlen(s);\n    if (n > 0 && s[n - 1] == 10) s[n - 1] = 0; /* 10 是换行符 */\n}\n\nint main(void) {\n    char buf[CAP] = "";\n    char line[128];\n\n    if (fgets(line, sizeof line, stdin) == NULL) return 0;\n    trim_newline(line);\n    if (safe_cat(buf, CAP, line) != 0) {\n        printf("buffer full\\n");\n        return 1;\n    }\n\n    if (fgets(line, sizeof line, stdin) == NULL) return 0;\n    trim_newline(line);\n    if (safe_cat(buf, CAP, line) != 0) {\n        printf("buffer full\\n");\n        return 1;\n    }\n\n    printf("%s\\n", buf);\n    printf("len=%lu\\n", (unsigned long)strlen(buf));\n    return 0;\n}\n```\n\n## 运行示例\n输入：`abc` / `def` → 输出 `abcdef` 与 `len=6`。\n若把 CAP 改成 5 再输入 `abc` 与 `def`，则第二次拼接时 `3 + 3 + 1 = 7 > 5`，输出 `buffer full`，缓冲区内容保持不变。\n\n要点：所有追加操作都先算后写；`memcpy` 的第三个参数是 `need + 1`，保证结尾的 0 一并写入。',
'[{"point":"正确实现 safe_cat：先算已用长度与待追加长度，判断 used+need+1 > cap 时返回错误且不修改目标","score":4},{"point":"用 memcpy 按精确长度拷贝并把结尾的 0 一并写入，杜绝 strcpy 的无长度检查","score":4},{"point":"读行使用 fgets 并去掉末尾换行符，不使用 gets","score":3},{"point":"处理空间不足的情况并给出提示，程序完整可编译运行且输出格式正确","score":4}]',15),

(70,'NCRE',3,'programming','**动态二维数组的分配、使用与释放**\n\n输入格式：\n- 第一行两个整数 m n（1 ≤ m, n ≤ 100），表示矩阵的行数与列数；\n- 接下来 m 行，每行 n 个整数。\n\n输出格式：\n- 前 m 行：每行输出 `row <i>: <该行元素之和>`（i 从 0 开始）；\n- 最后一行：`total: <全部元素之和>`。\n\n要求：\n1. 用 C99 写出完整程序；\n2. 必须用 `int **` **动态**分配二维数组（先分配行指针数组，再为每一行分配空间），不得使用 `int a[m][n]` 变长数组；\n3. 每次 malloc 都要检查返回值，中途失败时要**回滚**已分配的内存；\n4. 释放顺序必须正确（先释放各行，再释放行指针数组），并把指针置空。',
'[]','',
'解题路径是"两级分配"：先 malloc 一个长度为 m 的 `int *` 数组，再为每一行 malloc 长度为 n 的 int 数组；释放时必须**逆序**——先逐行 free，最后 free 行指针数组，顺序颠倒会使行指针丢失导致泄漏。关键点在于每行分配都可能失败，失败时要先把已经分配成功的行全部回收再退出，否则会泄漏。',
'## 思路\n1. `int **a = malloc(sizeof(int *) * m)`；\n2. 循环 `a[i] = malloc(sizeof(int) * n)`，一旦某行失败，先把 `a[0..i-1]` 全部 free，再 free(a)，然后返回错误；\n3. 读入数据后按行求和并累加总和；\n4. 释放：`for (i) free(a[i]); free(a); a = NULL;`。\n\n## 参考程序（C99）\n```c\n#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int m, n;\n    if (scanf("%d %d", &m, &n) != 2 || m <= 0 || n <= 0) return 0;\n\n    int **a = (int **)malloc(sizeof(int *) * m);\n    if (a == NULL) return 1;\n\n    for (int i = 0; i < m; i++) {\n        a[i] = (int *)malloc(sizeof(int) * n);\n        if (a[i] == NULL) {\n            for (int k = 0; k < i; k++) free(a[k]);   /* 回滚已分配的行 */\n            free(a);\n            return 1;\n        }\n    }\n\n    for (int i = 0; i < m; i++)\n        for (int j = 0; j < n; j++)\n            scanf("%d", &a[i][j]);\n\n    long long total = 0;\n    for (int i = 0; i < m; i++) {\n        long long row = 0;\n        for (int j = 0; j < n; j++) row += a[i][j];\n        total += row;\n        printf("row %d: %lld\\n", i, row);\n    }\n    printf("total: %lld\\n", total);\n\n    for (int i = 0; i < m; i++) { free(a[i]); a[i] = NULL; }\n    free(a);\n    a = NULL;\n    return 0;\n}\n```\n\n## 运行示例\n输入：\n```\n2 3\n1 2 3\n4 5 6\n```\n输出：\n```\nrow 0: 6\nrow 1: 15\ntotal: 21\n```\n\n要点：释放顺序与分配顺序相反；`a[i][j]` 的访问对这种"指针数组 + 每行独立分配"的布局是合法的，但各行在内存中**并不连续**，若需要连续可用一次性 malloc `m*n` 再加行指针索引。用 `long long` 累加避免 int 溢出。',
'[{"point":"正确用 int** 先分配行指针数组、再逐行分配空间","score":4},{"point":"每次 malloc 都检查返回值，并在中途失败时回滚已分配的行再退出","score":3},{"point":"正确读入数据并按行求和、累加总和（用 long long 防溢出）","score":3},{"point":"释放顺序正确：先逐行 free 再 free 行指针数组，并把指针置空","score":4},{"point":"程序完整可编译运行，输出格式与示例一致","score":2}]',16),

(66,'NCRE',3,'programming','**用指针实现子串查找（BF 算法）**\n\n输入格式：两行，第一行是主串 s（长度 ≤ 1000），第二行是模式串 t（长度 ≤ 100）。\n输出格式：两行\n```\nfirst: <t 在 s 中首次出现的下标，从 0 开始；未出现输出 -1>\ncount: <t 在 s 中不重叠出现的总次数>\n```\n\n要求：\n1. 用 C99 写出完整程序（含 main 与必要头文件）；\n2. 自己实现 `const char *my_strstr(const char *hay, const char *needle)`，**必须使用指针遍历**（不得用下标 `s[i]` 的形式），找不到返回 NULL；\n3. 统计次数时按**不重叠**计数（每次匹配成功后跳过整个模式串长度）；\n4. 用 fgets 读行并去掉末尾换行符。',
'[]','',
'解题路径是朴素 BF 匹配：主串指针 p 从头扫到尾，对每个 p 用另一个指针 r 逐字符比对模式串；若 r 走到模式串结尾说明匹配成功，否则 p 后移一位重新尝试。关键点在于比对失败时**主串指针只前进一位、模式串指针回到开头**的回溯方式，以及统计不重叠次数时每次要跳过整个模式长度而不是一位。',
'## 思路\n1. `for (const char *p = hay; *p != 0; p++)`：对每个起点尝试匹配；\n2. 内层 `const char *q = p, *r = needle;` 同步前进，直到 `*r == 0`（模式走完，匹配成功）或字符不等；\n3. 匹配成功返回 `p`，主串下标即 `p - hay`（指针相减得到的是元素个数）；\n4. 计数时 `p += strlen(needle)` 跳过已匹配部分，实现不重叠统计；\n5. 空模式串直接返回 hay（与标准库 strstr 行为一致）。\n\n## 参考程序（C99）\n```c\n#include <stdio.h>\n#include <string.h>\n\nstatic const char *my_strstr(const char *hay, const char *needle) {\n    if (needle[0] == 0) return hay;\n    for (const char *p = hay; *p != 0; p++) {\n        const char *q = p;\n        const char *r = needle;\n        while (*r != 0 && *q == *r) { q++; r++; }\n        if (*r == 0) return p;\n    }\n    return NULL;\n}\n\nstatic int count_occ(const char *hay, const char *needle) {\n    size_t len = strlen(needle);\n    if (len == 0) return 0;\n    int cnt = 0;\n    const char *p = hay;\n    while ((p = my_strstr(p, needle)) != NULL) {\n        cnt++;\n        p += len;              /* 不重叠：跳过整个模式串 */\n    }\n    return cnt;\n}\n\nstatic void trim_newline(char *s) {\n    size_t n = strlen(s);\n    if (n > 0 && s[n - 1] == 10) s[n - 1] = 0;\n}\n\nint main(void) {\n    char s[1005], t[105];\n    if (fgets(s, sizeof s, stdin) == NULL) return 0;\n    if (fgets(t, sizeof t, stdin) == NULL) return 0;\n    trim_newline(s);\n    trim_newline(t);\n\n    const char *pos = my_strstr(s, t);\n    if (pos == NULL) printf("first: -1\\n");\n    else printf("first: %ld\\n", (long)(pos - s));\n\n    printf("count: %d\\n", count_occ(s, t));\n    return 0;\n}\n```\n\n## 运行示例\n- 输入 `abababab` / `aba` → 输出 `first: 0`、`count: 2`（位置 0 与 4，位置 2 与它们重叠故不计）；\n- 输入 `hello world` / `xyz` → 输出 `first: -1`、`count: 0`。\n\n复杂度：BF 算法最坏 O(|s| × |t|)，平均情况下远好于此；若需线性时间可改用 KMP（预处理 next 数组，O(n + m)）。',
'[{"point":"正确使用指针遍历实现 BF 匹配（主串指针 p 与模式指针 r 同步推进，失败时 p 只前进一位）","score":4},{"point":"正确处理空模式串与找不到的情况（返回 NULL 并输出 -1）","score":3},{"point":"统计不重叠出现次数时每次匹配成功后跳过整个模式串长度","score":3},{"point":"用 fgets 安全读行并去掉末尾换行符，程序完整可编译运行","score":3},{"point":"说明时间复杂度 O(n·m) 及可改用 KMP 优化到线性","score":2}]',15);
